// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(mintAmount > 0 && burnAmount > 0);
        vm.assume(burnAmount <= mintAmount);
        vm.prank(address(this));
        c.mintToken(address(this), mintAmount);
        uint256 totalBefore = c.totalSupply();
        vm.prank(address(this));
        c.burn(burnAmount);
        assertTrue(c.totalSupply() < totalBefore);
    }
}
